{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "Tab",
    "subComponentOf": "TabList",
    "displayName": "Tab",
    "isHiddenFromOverview": true,
    "description": "Individual tab item that renders as a button or an anchor link, with selected-state styling and optional icons.",
    "playground": {
      "defaults": {
        "value": "tab-1",
        "label": "Tab"
      },
      "wrapper": {
        "component": "TabList",
        "props": {
          "value": "tab-1"
        }
      }
    },
    "examples": [
      {
        "label": "Describe a tab with help text",
        "code": "import {useRef, useState} from 'react';\nimport {Icon} from '@astryxdesign/core/Icon';\nimport {Tab, TabList} from '@astryxdesign/core/TabList';\nimport {Tooltip} from '@astryxdesign/core/Tooltip';\n\n// The tab is one button, so its help text is a Tooltip anchored on the Tab\n// through its ref, not a second button inside it. The tooltip describes the\n// tab itself. Render it after the TabList: the strip holds only tabs. The\n// info glyph in endContent is decorative.\nfunction SettingsTabs() {\n  const [value, setValue] = useState('general');\n  const generalRef = useRef(null);\n  return (\n    <>\n      <TabList value={value} onChange={setValue} role=\"tablist\" aria-label=\"Settings\">\n        <Tab\n          ref={generalRef}\n          value=\"general\"\n          label=\"General\"\n          panelId=\"panel-general\"\n          endContent={<Icon icon=\"info\" size=\"sm\" />}\n        />\n        <Tab value=\"advanced\" label=\"Advanced\" panelId=\"panel-advanced\" />\n      </TabList>\n      <Tooltip\n        content=\"Name, language, and time zone for this workspace.\"\n        anchorRef={generalRef}\n      />\n      <div id=\"panel-general\" role=\"tabpanel\" hidden={value !== 'general'}>\n        …\n      </div>\n      <div id=\"panel-advanced\" role=\"tabpanel\" hidden={value !== 'advanced'}>\n        …\n      </div>\n    </>\n  );\n}"
      }
    ],
    "props": [
      {
        "name": "value",
        "type": "string",
        "description": "Unique value for this tab, matched against TabListContext.value.",
        "required": true
      },
      {
        "name": "label",
        "type": "string",
        "description": "Accessible label for this tab. Used as visible text by default, or as aria-label when isLabelHidden is true.",
        "required": true
      },
      {
        "name": "isLabelHidden",
        "type": "boolean",
        "description": "Whether the label is visually hidden. When true, only the icon and endContent are displayed, and label is used as aria-label for accessibility.",
        "default": "false"
      },
      {
        "name": "href",
        "type": "string",
        "description": "URL to navigate to; when provided, the tab renders as an anchor element. Ignored in a TabList given an explicit role=\"tablist\"."
      },
      {
        "name": "panelId",
        "type": "string",
        "description": "Id of the panel this tab controls, wired up as aria-controls where the TabList speaks the tabs pattern. Put the same id on the panel element. No effect under the navigation pattern, and a development warning says so."
      },
      {
        "name": "as",
        "type": "LinkComponentType",
        "description": "Custom component to render instead of <a> for link tabs. Overrides the LinkProvider default. Only applies when href is provided."
      },
      {
        "name": "icon",
        "type": "ReactNode",
        "description": "Icon element shown when the tab is not selected.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "check",
              "size": "sm"
            }
          }
        ]
      },
      {
        "name": "selectedIcon",
        "type": "ReactNode",
        "description": "Icon element shown when the tab is selected; falls back to icon if not provided.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "checkCircle",
              "size": "sm"
            }
          }
        ]
      },
      {
        "name": "endContent",
        "type": "ReactNode",
        "description": "Content rendered after the label, such as a badge count or status dot. The tab is one button, so endContent holds only non-interactive content: no button, link, InfoTip, or other focusable control. To explain a tab, anchor a Tooltip on the Tab through its ref, render it after the TabList, and put a decorative info Icon here.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "chevronDown",
              "size": "sm"
            }
          },
          {
            "__element": "Badge",
            "props": {
              "label": "3"
            }
          }
        ]
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value: not an inline style object like style={{}}."
      }
    ],
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/TabList",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
